import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Nav, Navbar } from 'react-bootstrap';
import 'bootstrap/dist/css/bootstrap.min.css';
import './App.css';

import Dashboard from './components/Dashboard';
import Scheduler from './components/Scheduler';
import MemoryManagement from './components/MemoryManagement';
import FileSystem from './components/FileSystem';
import Synchronization from './components/Synchronization';
import Terminal from './components/Terminal';

function App() {
  const [activeTab, setActiveTab] = useState('dashboard');

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard />;
      case 'scheduler':
        return <Scheduler />;
      case 'memory':
        return <MemoryManagement />;
      case 'filesystem':
        return <FileSystem />;
      case 'sync':
        return <Synchronization />;
      case 'terminal':
        return <Terminal />;
      default:
        return <Dashboard />;
    }
  };

  return (
    <div className="App" style={{ height: '100vh', display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
      <Navbar bg="dark" variant="dark" expand="lg" style={{ flexShrink: 0 }}>
        <Container fluid>
          <Navbar.Brand href="#home">
            <strong>CoreX OS</strong> - Virtual Operating System Simulator
          </Navbar.Brand>
          <Navbar.Toggle />
          <Navbar.Collapse>
            <Nav className="ms-auto">
              <Nav.Link onClick={() => setActiveTab('dashboard')} active={activeTab === 'dashboard'}>
                Dashboard
              </Nav.Link>
              <Nav.Link onClick={() => setActiveTab('scheduler')} active={activeTab === 'scheduler'}>
                Scheduler
              </Nav.Link>
              <Nav.Link onClick={() => setActiveTab('memory')} active={activeTab === 'memory'}>
                Memory
              </Nav.Link>
              <Nav.Link onClick={() => setActiveTab('filesystem')} active={activeTab === 'filesystem'}>
                File System
              </Nav.Link>
              <Nav.Link onClick={() => setActiveTab('sync')} active={activeTab === 'sync'}>
                Synchronization
              </Nav.Link>
              <Nav.Link onClick={() => setActiveTab('terminal')} active={activeTab === 'terminal'}>
                Terminal
              </Nav.Link>
            </Nav>
          </Navbar.Collapse>
        </Container>
      </Navbar>

      <Container fluid style={{ 
        flex: 1, 
        overflow: activeTab === 'terminal' ? 'hidden' : 'auto',
        padding: activeTab === 'terminal' ? 0 : '1rem'
      }}>
        {renderContent()}
      </Container>

      {activeTab !== 'terminal' && (
        <footer className="py-3 bg-light text-center" style={{ flexShrink: 0 }}>
          <p className="mb-0">CoreX OS v1.0 | Educational Operating System Simulator</p>
        </footer>
      )}
    </div>
  );
}

export default App;
